string[] inputs = ["42", "abc", ""];

foreach (string input in inputs)
{
    try
    {
        int value = int.Parse(input);
        Console.WriteLine($"Parsed {value}");
    }
    catch (FormatException) when (input.Length == 0)
    {
        Console.WriteLine("Empty input");
    }
    catch (FormatException ex)
    {
        Console.WriteLine($"Not a number: {ex.Message}");
    }
    finally
    {
        Console.WriteLine("Finished one input");
    }
}

try
{
    Transfer(500m, balance: 100m);
}
catch (InsufficientFundsException ex)
{
    Console.WriteLine($"{ex.Message} (short by {ex.Shortfall})");
}

try
{
    Transfer(-5m, balance: 100m);
}
catch (ArgumentOutOfRangeException ex)
{
    Console.WriteLine($"Bad argument: {ex.ParamName}");
}

Transfer(80m, balance: 100m);

void Transfer(decimal amount, decimal balance)
{
    ArgumentOutOfRangeException.ThrowIfNegativeOrZero(amount);
    if (amount > balance)
    {
        throw new InsufficientFundsException(amount - balance);
    }
    Console.WriteLine($"Transferred {amount}");
}

class InsufficientFundsException(decimal shortfall)
    : Exception($"Insufficient funds: {shortfall} more needed")
{
    public decimal Shortfall { get; } = shortfall;
}

try
{
    LoadConfig("settings.json");
}
catch (Exception ex)
{
    Console.WriteLine(ex.Message);
    Console.WriteLine($"Caused by: {ex.InnerException?.GetType().Name}");
}

void LoadConfig(string path)
{
    try
    {
        File.ReadAllText(path);
    }
    catch (FileNotFoundException ex)
    {
        throw new InvalidOperationException($"Configuration file '{path}' is missing.", ex);
    }
}
